:first-child{color:#c1b6a7}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a7ad78;box-shadow:0 0 8px #a7ad7888;margin-right:6px}.arena-head span:last-child{color:#a09491}.arena{position:relative;flex:1;min-height:0;overflow:hidden;background:#17151a}.arena canvas{width:100%;height:100%;display:block;touch-action:none}.arena-foot{height:34px;border-top:1px solid #302a2e}.arena-foot span:first-child{color:#d8b27b}.arena-foot b{font-weight:400}.arena-foot span:last-child{color:#8e858b}.toast{position:absolute;top:15px;left:50%;transform:translate(-50%,-8px);padding:8px 13px;background:#19161be8;border:1px solid #5b4445;color:#e3c28d;font:10px 'DM Mono',monospace;letter-spacing:.4px;opacity:0;pointer-events:none;transition:all .22s;white-space:nowrap;z-index:3}.toast.show{opacity:1;transform:translate(-50%,0)}.start-screen,.end-screen{position:absolute;inset:0;z-index:2;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;background:radial-gradient(ellipse at center,rgba(26,18,23,.88),rgba(13,12,16,.91));backdrop-filter:blur(2px)}.hidden{display:none!important}.sigil{font-size:30px;color:var(--gold);text-shadow:0 0 24px #d39a5877;margin-bottom:10px}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:2.5px;color:#aa8d78}.start-screen h1,.end-screen h2{font:600 clamp(28px,4vw,47px)/1.15 'Unbounded',sans-serif;letter-spacing:1px;margin:14px 0;color:#e8dfd1}.start-screen h1 em,.end-screen h2 em{font-style:normal;color:#bf7768}.start-screen p,.end-screen p{font-size:12px;line-height:1.7;color:#aaa0a0;margin:6px 0 19px}.primary-button{background:#bd755f;color:#171216;border:0;padding:13px 22px;font:600 10px 'DM Mono',monospace;letter-spacing:1.5px;cursor:pointer;box-shadow:0 5px 25px #bf735533}.primary-button span{padding-left:18px;font-size:15px}.primary-button:active{transform:translateY(1px)}.start-hint{margin-top:20px;color:#716b73;font:8px 'DM Mono',monospace;letter-spacing:1px}.combat-caption{position:absolute;bottom:10px;left:0;right:0;text-align:center;color:#8a7a7b;font:9px 'DM Mono',monospace;letter-spacing:.6px;pointer-events:none;opacity:.85}.note-count{float:right;color:#c79867;font-size:15px}.enemy-glyph{height:37px;width:37px;background:#2c2025;border:1px solid #70464b;border-radius:50%;display:grid;place-items:center;color:#d77d71;font-size:22px;text-shadow:0 0 13px #d24747}.enemy-desc{margin-top:0}.omens{min-height:100px;max-height:190px;overflow:hidden}.omen{font-size:10px;line-height:1.45;color:#aaa0a4;margin:0 0 10px;padding-left:1px}.omen span{color:#c28d66;margin-right:7px}.journal{border-top:1px solid var(--line);margin-top:12px;padding-top:14px;position:relative}.journal-seal{color:#9e796d;font-size:16px}.journal p{font:italic 11px/1.6 Georgia,serif;color:#b6a9a4;margin:7px 0}.journal small{font:8px 'DM Mono',monospace;color:#716b71;letter-spacing:.8px}.controls{height:122px;flex:none;border-top:1px solid #302c32;display:flex;align-items:center;justify-content:space-between;padding:8px 8px 0}.control-label{display:block;font:8px 'DM Mono',monospace;color:#766f77;letter-spacing:1.5px;margin-bottom:7px}.dpad{width:118px;height:79px;display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);gap:3px}.dpad button,.action{border:1px solid #383239;color:#c9c0b9;background:linear-gradient(135deg,#252128,#1b191e);touch-action:none;user-select:none;-webkit-user-select:none}.dpad button{font-size:11px}.dpad button[data-key=up]{grid-column:2;grid-row:1}.dpad button[data-key=left]{grid-column:1;grid-row:2}.dpad button[data-key=right]{grid-column:3;grid-row:2}.dpad button[data-key=down]{grid-column:2;grid-row:3}.dpad-center{grid-column:2;grid-row:2;color:#786b6b!important;background:#19171b!important}.dpad button:active,.action:active,.action.active{background:#62413e;color:#ffe0b4;transform:scale(.97)}.control-tip{font:10px 'DM Mono',monospace;color:#777078;letter-spacing:.2px;text-align:center}.control-tip b{color:#c39071;margin-right:4px}.action-buttons{display:flex;gap:6px}.action{width:72px;height:78px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;cursor:pointer}.action>span{font-size:21px;color:#d69d71}.action small{font:8px 'DM Mono',monospace;letter-spacing:.7px}.action kbd{font:7px 'DM Mono',monospace;color:#716a72;margin-top:3px}.dodge>span{color:#9aa677}.heal>span{color:#cb6e68}.mobile-note{display:none}
