(() => {
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = { hp:$('hpText'), hpBar:$('hpBar'), ember:$('emberText'), emberBar:$('emberBar'), floor:$('floorText'), name:$('enemyName'), type:$('enemyType'), glyph:$('enemyGlyph'), desc:$('enemyDesc'), room:$('roomLabel'), objective:$('objective'), kills:$('killText'), habit:$('habitName'), habitText:$('habitText'), adapt:$('adaptBar'), adaptText:$('adaptText'), omens:$('omens'), toast:$('toast'), caption:$('combatCaption') };
  const rooms = [
    {name:'THE MOUTHING HALL', foe:'THE HOLLOWLING', glyph:'◉', kind:'HUNGER', desc:'A thing stitched from old hunger. It watches how you move.', hp:55, speed:58, damage:10, color:'#a75d62'},
    {name:'THE VEIN CHAPEL', foe:'THE TENDRIL SAINT', glyph:'✣', kind:'GROWTH', desc:'A prayer with too many limbs. Its roots turn toward your warmth.', hp:75, speed:68, damage:12, color:'#8e8063'},
    {name:'THE WET ARCHIVE', foe:'THE MOURNING MASK', glyph:'◍', kind:'MIMIC', desc:'It wears the last face it saw. It has started wearing yours.', hp:91, speed:75, damage:14, color:'#8e687c'},
    {name:'THE GNAWING WELL', foe:'THE PALE GNAWER', glyph:'⦿', kind:'PREDATOR', desc:'A blind thing that hears your heartbeat change.', hp:112, speed:86, damage:16, color:'#a47659'},
    {name:'THE LAST QUIET', foe:'THE THING THAT LISTENS', glyph:'✹', kind:'THE DEEP', desc:'It has learned every lesson. There is only one left to teach.', hp:150, speed:90, damage:19, color:'#bd6359'}
  ];
  let W=900,H=620,dpr=1,started=false,ended=false,last=0,now=0,toastTimer=0,soundOn=false,audio;
  let player,enemy,particles=[],floaters=[],keys={},touch={},stats={attacks:0,dodges:0,heals:0,steps:0}, habit='UNREADABLE', roomIndex=0, clearTimer=0, screenShake=0, floorTime=0;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y), rand=(a,b)=>a+Math.random()*(b-a);
  function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(r.width*dpr));canvas.height=Math.max(1,Math.floor(r.height*dpr));W=900;H=canvas.height/dpr/(canvas.width/dpr/W);H=Math.max(510,H);}
  window.addEventListener('resize',resize); resize();
  const playerStart=()=>({x:W*.5,y:H*.68,r:15,hp:100,maxHp:100,ember:3,maxEmber:3,faceX:0,faceY:-1,attackCd:0,dodgeCd:0,dodgeTime:0,invuln:0,healCd:0,walk:0});
  function spawnEnemy(){const data=rooms[roomIndex];enemy={x:W*.5,y:H*.32,r:25,hp:data.hp,maxHp:data.hp,phase:'stalk',timer:1.1+Math.random(),attackCd:1.2,hit:0,guard:0,slow:0,attackX:0,attackY:0,dead:false,step:Math.random()*10,adaptLevel:0,guardFlash:0};}
  function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.55}
  function note(text){const p=document.createElement('p');p.className='omen';p.innerHTML='<span>✦</span> '+text;ui.omens.prepend(p);while(ui.omens.children.length>5)ui.omens.lastChild.remove()}
  function setHabit(text,sub){ui.habit.textContent=text;ui.habitText.textContent=sub}
  function start(){if(started&&!ended)return;started=true;ended=false;roomIndex=0;stats={attacks:0,dodges:0,heals:0,steps:0};player=playerStart();particles=[];floaters=[];$('startScreen').classList.add('hidden');$('endScreen').classList.add('hidden');ui.omens.innerHTML='<p class="omen"><span>✦</span> You have entered the mouthing hall.</p>';beginRoom();updateUI();last=performance.now();requestAnimationFrame(loop);}
  function beginRoom(){const data=rooms[roomIndex];spawnEnemy();ui.floor.innerHTML=`0${roomIndex+1} <i>/ 05</i>`;ui.name.textContent=data.foe;ui.type.textContent=`${data.kind} · 0${roomIndex+1}`;ui.glyph.textContent=data.glyph;ui.desc.textContent=data.desc;ui.room.textContent=data.name;ui.objective.textContent=roomIndex===4?'FACE THE THING THAT LISTENS':'SURVIVE THE HALL';ui.kills.textContent=`0 / 1 FOES`;ui.caption.textContent=roomIndex===4?'A silence with a pulse...':'A wet sound stirs in the dark...';setHabit(habit,habit==='UNREADABLE'?'Keep moving. Watch what watches you.':'It remembers your last lesson.');showToast(roomIndex===0?'The dark draws near.':`Descent ${roomIndex+1}: ${data.name.toLowerCase()}`);}
  function updateUI(){if(!player)return;ui.hp.textContent=`${Math.ceil(player.hp)} `;ui.hp.innerHTML=`${Math.ceil(player.hp)} <i>/ ${player.maxHp}</i>`;ui.hpBar.style.width=`${100*player.hp/player.maxHp}%`;ui.ember.innerHTML=`${player.ember} <i>/ ${player.maxEmber}</i>`;ui.emberBar.style.width=`${100*player.ember/player.maxEmber}%`;let sum=stats.attacks+stats.dodges+stats.heals+stats.steps*.15||1;let attack=stats.attacks/sum,dodge=stats.dodges/sum,heal=stats.heals/sum,move=stats.steps*.15/sum;let max=Math.max(attack,dodge,heal,move);if(max<.3){habit='UNREADABLE';setHabit(habit,'Keep moving. Watch what watches you.')}else if(max===attack){habit='THE STRIKER';setHabit(habit,'It braces for your next blow.');}else if(max===dodge){habit='THE EVADER';setHabit(habit,'It is leading its strikes ahead of you.');}else if(max===heal){habit='THE WOUNDED';setHabit(habit,'It lunges when you reach for the ember.');}else{habit='THE RESTLESS';setHabit(habit,'It tracks your favorite paths.');}let learned=clamp(Math.round((stats.attacks+stats.dodges+stats.heals+stats.steps*.12)*2.1),0,100);ui.adapt.style.width=learned+'%';ui.adaptText.textContent=learned+'%';}
  function sound(freq=130,dur=.09,type='triangle'){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch(e){}}
  function burst(x,y,color,n=8,power=120){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=rand(power*.25,power);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.25,.65),max:.65,r:rand(1,3),color});}}
  function floatText(x,y,text,color='#efc18a'){floaters.push({x,y,text,color,life:.8})}
  function attack(){if(!started||ended||player.attackCd>0)return;player.attackCd=.42;stats.attacks++;let d=dist(player,enemy), dx=enemy.x-player.x,dy=enemy.y-player.y, len=Math.hypot(dx,dy)||1;player.faceX=dx/len;player.faceY=dy/len;burst(player.x+player.faceX*25,player.y+player.faceY*25,'#d7ad82',3,45);sound(270,.08,'sawtooth');if(d<88){if(enemy.guard>0){floatText(enemy.x,enemy.y-28,'READ',' #d3a27a');enemy.guardFlash=.25;burst(enemy.x,enemy.y,'#deb778',5,80);showToast('It anticipated the strike.');}else{let dmg=18+Math.random()*5;enemy.hp-=dmg;enemy.hit=.16;enemy.slow=.15;floatText(enemy.x,enemy.y-25,`-${Math.round(dmg)}`);burst(enemy.x,enemy.y,'#d77b6c',10,140);screenShake=5;sound(100,.12,'square');if(enemy.hp<=0)killEnemy()}}else{floatText(player.x,player.y-28,'MISS','#b6a8a2')}}
  function dodge(){if(!started||ended||player.dodgeCd>0)return;let dx=(keys.right||keys.ArrowRight||touch.right?1:0)-(keys.left||keys.ArrowLeft||touch.left?1:0),dy=(keys.down||keys.ArrowDown||touch.down?1:0)-(keys.up||keys.ArrowUp||touch.up?1:0);if(!dx&&!dy){dx=player.faceX;dy=player.faceY}let n=Math.hypot(dx,dy)||1;player.faceX=dx/n;player.faceY=dy/n;player.dodgeTime=.23;player.invuln=.32;player.dodgeCd=.9;stats.dodges++;player.x=clamp(player.x+player.faceX*72,48,W-48);player.y=clamp(player.y+player.faceY*72,75,H-55);burst(player.x,player.y,'#9dac86',10,105);sound(390,.1);updateUI()}
  function heal(){if(!started||ended)return;if(player.ember<=0||player.hp>=player.maxHp){showToast(player.ember<=0?'No ember left.':'Your wounds have closed.');return}player.ember--;player.hp=Math.min(player.maxHp,player.hp+30);stats.heals++;floatText(player.x,player.y-28,'+30','#b8c88d');burst(player.x,player.y,'#c3b879',13,90);showToast('An ember catches. The dark is watching.');sound(520,.18);updateUI()}
  function killEnemy(){enemy.dead=true;ui.kills.textContent='1 / 1 FOES';ui.caption.textContent='It falls quiet. For a moment.';burst(enemy.x,enemy.y,'#bd776a',36,190);floatText(enemy.x,enemy.y-32,'UNMADE','#e1b682');sound(75,.45,'sawtooth');clearTimer=1.8;player.hp=Math.min(player.maxHp,player.hp+8);player.ember=Math.min(player.maxEmber,player.ember+1);note(`${rooms[roomIndex].foe.toLowerCase()} has gone still. The descent deepens.`);showToast('The dark gives back a little warmth.');}
  function hurtPlayer(amount){if(player.invuln>0)return;player.hp-=amount;player.invuln=.75;screenShake=8;burst(player.x,player.y,'#c85958',14,130);floatText(player.x,player.y-25,`-${amount}`,'#ed7770');sound(65,.2,'square');if(player.hp<=0){player.hp=0;finish(false)}updateUI()}
  function finish(win){ended=true;$('endScreen').classList.remove('hidden');$('endEyebrow').textContent=win?'THE DARK HAS A NEW NAME':'THE DEEP REMEMBERS';$('endTitle').innerHTML=win?'YOU WALKED<br><em>OUT ALIVE</em>':'THE QUIET<br><em>CLAIMS YOU</em>';$('endCopy').textContent=win?'Five halls. Five lessons. You left the dark with nothing new to learn.':`The dark learned your ways in ${roomIndex+1} hall${roomIndex?'s':''}. Maybe next time, teach it something else.`;ui.caption.textContent=win?'A thread of dawn, impossibly far away.':'The silence closes over you.'}
  function movement(dt){let x=(keys.d||keys.D||keys.ArrowRight||touch.right?1:0)-(keys.a||keys.A||keys.ArrowLeft||touch.left?1:0),y=(keys.s||keys.S||keys.ArrowDown||touch.down?1:0)-(keys.w||keys.W||keys.ArrowUp||touch.up?1:0);if(x||y){let n=Math.hypot(x,y);x/=n;y/=n;player.faceX=x;player.faceY=y;let speed=player.dodgeTime>0?420:190;player.x=clamp(player.x+x*speed*dt,42,W-42);player.y=clamp(player.y+y*speed*dt,72,H-47);player.walk+=dt*10;stats.steps+=dt;}}
  function enemyAI(dt){if(enemy.dead)return;enemy.hit=Math.max(0,enemy.hit-dt);enemy.slow=Math.max(0,enemy.slow-dt);enemy.guard=Math.max(0,enemy.guard-dt);enemy.guardFlash=Math.max(0,enemy.guardFlash-dt);enemy.attackCd-=dt;enemy.step+=dt*3;let dx=player.x-enemy.x,dy=player.y-enemy.y,d=Math.hypot(dx,dy)||1,nx=dx/d,ny=dy/d;let data=rooms[roomIndex],agility=1+roomIndex*.055;
    if(enemy.phase==='stalk'){let speed=data.speed*agility*(enemy.slow?0.35:1);let attackRatio=stats.attacks/(stats.attacks+stats.dodges+stats.heals+1);if(attackRatio>.43&&enemy.adaptLevel<1){enemy.adaptLevel=1;enemy.guard=1.25;showToast('It raises a guard against your rhythm.');ui.caption.textContent='It has learned to brace for your strikes.'}if(enemy.guard>0)speed*=.76;
